previewCss:
.darma-loader-darma-b10-radial-equalizer { --accent: var(--loader-color, #8b5cf6); --accent-2: var(--loader-secondary-color, #ec4899); width: var(--loader-size, 90px); height: var(--loader-size, 90px); position: relative; }
.darma-loader-darma-b10-radial-equalizer span { position: absolute; bottom: 50%; left: 50%; width: calc(var(--loader-size, 90px) * .045); height: calc(var(--loader-size, 90px) * .22); margin-left: calc(var(--loader-size, 90px) * -.0225); background: linear-gradient(var(--accent-2), var(--accent)); border-radius: 3px; transform-origin: 50% 100%; animation: darma-loader-darma-b10-radial-equalizer-eq calc(var(--loader-speed, 1s) * 1.1) ease-in-out infinite; }
.darma-loader-darma-b10-radial-equalizer span:nth-child(1) { transform: rotate(0deg); animation-delay: 0s; }
.darma-loader-darma-b10-radial-equalizer span:nth-child(2) { transform: rotate(30deg); animation-delay: calc(var(--loader-speed, 1s) * .08); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(3) { transform: rotate(60deg); animation-delay: calc(var(--loader-speed, 1s) * .16); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(4) { transform: rotate(90deg); animation-delay: calc(var(--loader-speed, 1s) * .24); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(5) { transform: rotate(120deg); animation-delay: calc(var(--loader-speed, 1s) * .32); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(6) { transform: rotate(150deg); animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(7) { transform: rotate(180deg); animation-delay: calc(var(--loader-speed, 1s) * .48); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(8) { transform: rotate(210deg); animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(9) { transform: rotate(240deg); animation-delay: calc(var(--loader-speed, 1s) * .32); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(10) { transform: rotate(270deg); animation-delay: calc(var(--loader-speed, 1s) * .24); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(11) { transform: rotate(300deg); animation-delay: calc(var(--loader-speed, 1s) * .16); }
.darma-loader-darma-b10-radial-equalizer span:nth-child(12) { transform: rotate(330deg); animation-delay: calc(var(--loader-speed, 1s) * .08); }
@keyframes darma-loader-darma-b10-radial-equalizer-eq { 0%, 100% { scale: 1 .45; } 50% { scale: 1 1.25; } }

